import{_ as t,o as e,c as r,a2 as d}from"./chunks/framework.doxMM-x8.js";const p=JSON.parse('{"title":"产品范围与架构","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/architecture/lab-word","contentType":"concept","prev":false,"next":false},"headers":[],"relativePath":"architecture/lab-word.md","filePath":"architecture/lab-word.md"}'),o={name:"architecture/lab-word.md"};function n(l,a,s,i,c,b){return e(),r("div",null,[...a[0]||(a[0]=[d(`<h1 id="产品范围与架构" tabindex="-1">产品范围与架构 <a class="header-anchor" href="#产品范围与架构" aria-label="Permalink to &quot;产品范围与架构&quot;">​</a></h1><p>Lab Word 的产品目标是实验室数字孪生。当前正式应用提供单模型查看与会话内资产库；持久世界和后端虚拟设备是已批准的下一阶段。术语见 <a href="https://github.com/CaiZongyuan/labworld/blob/e080eb3aca90c0e62358b3c5ecd6f779b2b1104e/CONTEXT.md" target="_blank" rel="noreferrer">CONTEXT</a>。</p><h2 id="模型与设备的关系" tabindex="-1">模型与设备的关系 <a class="header-anchor" href="#模型与设备的关系" aria-label="Permalink to &quot;模型与设备的关系&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Lab ──登记──&gt; Entity（设备等对象）&lt;──定义── Asset</span></span>
<span class="line"><span>                 │</span></span>
<span class="line"><span>                 └──由 Scene Node 呈现 &lt;──外观── Asset Representation</span></span></code></pre></div><p>这是 Foundation V1 的目标关系：Equipment Model 是三维资产表示，Equipment Instance 是设备类 Entity；Scene Node 的身份与摆放独立于设备身份。同一模型可表示多台设备，同一设备也可有多个节点。当前单模型查看器尚不建立这些持久对象和布局。</p><h2 id="已有实现与目标接入" tabindex="-1">已有实现与目标接入 <a class="header-anchor" href="#已有实现与目标接入" aria-label="Permalink to &quot;已有实现与目标接入&quot;">​</a></h2><table tabindex="0"><thead><tr><th>范围</th><th>当前状态</th><th>后续责任</th></tr></thead><tbody><tr><td>通用应用壳、身份、成员、知识库</td><td>现有应用代码</td><td>为 Lab 提供宿主与共享能力</td></tr><tr><td>Lab Viewer 与会话资产库</td><td>已集成，已有正式行为验证</td><td>扩展持久资产及多对象表示</td></tr><tr><td>Lab 导航与登录后默认入口</td><td>已由显式组装接入</td><td>保持宿主和 Lab 职责分离</td></tr><tr><td>Foundation V1</td><td>体验已接受，规格/实施票已发布</td><td>建立持久世界与后端虚拟设备运行</td></tr><tr><td>真实设备与协议接入</td><td>后续范围</td><td>按实际来源增加适配与执行合同</td></tr></tbody></table><p><a href="https://github.com/CaiZongyuan/labworld/blob/e080eb3aca90c0e62358b3c5ecd6f779b2b1104e/docs/adr/0005-lab-digital-twin-on-saas-foundation.md" target="_blank" rel="noreferrer">ADR 0005</a>选择复用现有 SaaS 底座：Lab 拥有设备与布局业务，Core 保持身份、成员等公共职责。接入点见<a href="./project-structure">项目结构</a>。</p><h2 id="当前呈现层边界" tabindex="-1">当前呈现层边界 <a class="header-anchor" href="#当前呈现层边界" aria-label="Permalink to &quot;当前呈现层边界&quot;">​</a></h2><p>首版查看一份资源内嵌的 GLB，支持文件选择与拖入、自动居中与取景、旋转/缩放/平移、点击选择、回到示例和渲染指标。导入文件停留在浏览器会话，不增加服务器上传或云资产库。</p><p>当前实现保持模型原始尺度，并在外部资源依赖、无几何或解码失败时反馈错误、保留前一个可用模型。替换与离开页面释放独占 GPU 资源，快速切换防止旧结果覆盖新模型；后续多实例改造需保持这些合同。</p><p>Three.js 相关代码已随 Lab 页面按需加载，并纳入正式包体预算。预览的构建与软件渲染指标不代表目标硬件性能。</p><h2 id="继续开发" tabindex="-1">继续开发 <a class="header-anchor" href="#继续开发" aria-label="Permalink to &quot;继续开发&quot;">​</a></h2><p>先按<a href="./../guides/lab-viewer">查看器指南</a>观察现有功能。Foundation V1 从<a href="https://github.com/CaiZongyuan/labworld/issues/1" target="_blank" rel="noreferrer">规格 #1</a>及其实施票继续，接手入口为<a href="https://github.com/CaiZongyuan/labworld/blob/e080eb3aca90c0e62358b3c5ecd6f779b2b1104e/docs/handoffs/digital-twin-foundation-v1.md" target="_blank" rel="noreferrer">开发交接</a>；职责规则见<a href="./module-boundaries">模块边界</a>。</p><hr><p>源码版本：<code>e080eb3aca90</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/e080eb3aca90c0e62358b3c5ecd6f779b2b1104e/docs/architecture/lab-word.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,16)])])}const u=t(o,[["render",n]]);export{p as __pageData,u as default};
